(LM.FINALS = LM.FINALS || {})["A1"] = {"version":1,"id":"final-a1","level":"A1","kind":"level-test","title":"A1 final test","intro":"Thirty questions from the whole of A1; each attempt draws 20. You need 80% to pass. You see the explanations at the end.","draw":20,"passPercent":80,"defaultMode":"exam","items":[{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-01","topic":"a1-cases-nominative","type":"multiple-choice","kind":"form","prompt":"To jest ___ dom.","options":["nowy","nowa","nowe","nowego"],"correct":0,"explanation":"Dom is masculine, and after to jest the phrase stays in the nominative: nowy dom.","optionNotes":[null,"-a is the feminine ending: nowa praca.","-e is the neuter singular ending: nowe auto.","-ego is the masculine accusative of people and animals (mam nowego kolegę) and the genitive (nie mam nowego domu)."],"category":"cases"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-02","topic":"a1-cases-accusative","type":"gap-fill","text":"Lubię {{1}}.","gaps":[{"accepted":["zieloną herbatę"],"hint":"(zielona herbata)"}],"explanation":"Lubić takes the accusative. Feminine: the adjective -a → -ą, the noun -a → -ę.","category":"cases"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-03","topic":"a1-verbs-byc","type":"multiple-choice","kind":"form","prompt":"My ___ z Kanady.","options":["jesteśmy","są","jesteście","jestem"],"correct":0,"explanation":"My (we) goes with jesteśmy.","optionNotes":[null,"Są is for oni / one (they).","Jesteście is for wy (you, plural).","Jestem is for ja (I)."],"category":"verbs"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-04","topic":"a1-verbs-present-conjugations","type":"short-answer","prompt":"Codziennie ___ gazetę. (czytać, I)","accepted":["czytam"],"explanation":"Czytać follows the -am, -asz pattern: (ja) czytam, (ty) czytasz.","category":"verbs"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-05","topic":"a1-grammar-questions-negation","type":"multiple-choice","kind":"form","prompt":"— ___ mieszkasz? — W Gdańsku.","options":["Gdzie","Kiedy","Kto","Ile"],"correct":0,"explanation":"The answer is a place, so the question word is gdzie (where).","optionNotes":[null,"Kiedy asks about time (when).","Kto asks about a person (who).","Ile asks about an amount (how many, how much)."],"category":"grammar"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-06","topic":"a1-grammar-gender-of-nouns","type":"multiple-choice","kind":"form","prompt":"___ okno jest otwarte.","options":["Ten","Ta","To","Te"],"correct":2,"explanation":"Nouns ending in -o are (almost always) neuter: to okno.","optionNotes":["Ten is masculine: ten dom.","Ta is feminine: ta kawa.",null,"Te is plural: te okna."],"category":"grammar"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-07","topic":"a1-vocabulary-numbers-days-months","type":"multiple-choice","kind":"meaning","prompt":"Tydzień ma ___ dni.","options":["pięć","sześć","siedem","osiem"],"correct":2,"explanation":"A week has seven days: siedem.","optionNotes":["Pięć = five.","Sześć = six.",null,"Osiem = eight."],"category":"vocabulary"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-08","topic":"a1-vocabulary-food-drink","type":"match","mode":"translation","prompt":"Match the English words with their Polish equivalents.","pairs":[["bread","chleb"],["cheese","ser"],["water","woda"],["breakfast","śniadanie"]],"explanation":"Bread = chleb, cheese = ser, water = woda, breakfast = śniadanie.","category":"vocabulary"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-09","topic":"a1-functions-greetings-introductions","type":"multiple-choice","kind":"function","prompt":"In the morning you walk into a shop. You say:","options":["Dzień dobry!","Dobranoc!","Do widzenia!","Na zdrowie!"],"correct":0,"explanation":"Dzień dobry is the polite greeting during the day.","optionNotes":[null,"Dobranoc = good night, said before going to bed.","Do widzenia = goodbye, said when you leave.","Na zdrowie = cheers, or bless you after a sneeze."],"category":"functions"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-10","topic":"a1-functions-ordering-shopping","type":"reorder","context":"In a café: I'd like a coffee with milk, please.","answers":["Poproszę kawę z mlekiem.","Kawę z mlekiem poproszę."],"explanation":"Poproszę takes the accusative: kawa → kawę. Z mlekiem stays next to kawę.","category":"functions"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-11","topic":"a1-grammar-alphabet-pronunciation","type":"multiple-choice","kind":"form","prompt":"Which word has the same first sound as żona?","options":["ręka","zima","rzeka","szkoła"],"correct":2,"explanation":"Rz and ż are one and the same sound, like \"s\" in pleasure: rzeka, żona.","optionNotes":["R in ręka is an ordinary rolled r.","Zi in zima is a soft \"zh\", not the hard ż.",null,"Sz in szkoła is \"sh\", a sound without voice."],"category":"grammar"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-12","topic":"a1-grammar-pronouns-pan-pani","type":"multiple-choice","kind":"function","prompt":"You ask an older woman you have just met how she is. You say:","options":["Jak się masz?","Jak się pani ma?","Jak się macie?","Jak się pani masz?"],"correct":1,"explanation":"With a stranger use pani and the \"she\" form of the verb: Jak się pani ma?","optionNotes":["Jak się masz? uses ty: only for friends, family and children.",null,"Macie is the wy form: for several friends, never a polite form for one person.","Pani takes the \"she\" form ma, not the ty form masz."],"category":"grammar"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-13","topic":"a1-grammar-pronouns-pan-pani","type":"multiple-choice","kind":"form","prompt":"Ola i Kasia? ___ są w domu.","options":["Oni","Ona","Ono","One"],"correct":3,"explanation":"A group with no man in it is one.","optionNotes":["Oni needs at least one man in the group.","Ona is one woman (she), and są is plural.","Ono is \"it\", for neuter nouns like dziecko.",null],"category":"grammar"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-14","topic":"a1-grammar-possessives-demonstratives","type":"multiple-choice","kind":"form","prompt":"Znasz ___ brata?","options":["mojego","mój","moja","moją"],"correct":0,"explanation":"Brat is the object and a male person, so \"my\" takes -ego: mojego brata.","optionNotes":[null,"Mój is the nominative; a male person as an object needs mojego.","Moja is feminine, and brat is masculine.","Moją is the feminine accusative: moją siostrę."],"category":"grammar"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-15","topic":"a1-verbs-common-irregular","type":"multiple-choice","kind":"form","prompt":"Moi rodzice ___ kolację o siódmej.","options":["jadą","jemy","jedzą","je"],"correct":2,"explanation":"Jeść (eat) in the oni form is jedzą.","optionNotes":["Jadą is \"they are going\" (jechać), not \"they eat\".","Jemy is the my form (we eat).",null,"Je is the \"he / she\" form."],"category":"verbs"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-16","topic":"a1-verbs-modal-verbs-basics","type":"translate","source":"I can't swim. (I never learnt how)","accepted":["Nie umiem pływać.","Ja nie umiem pływać.","Nie potrafię pływać.","Ja nie potrafię pływać."],"hint":"a skill: umieć + infinitive","explanation":"A skill you have learnt is umieć, and the second verb is the infinitive: Nie umiem pływać.","category":"verbs"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-17","topic":"a1-verbs-going-isc-jechac","type":"multiple-choice","kind":"form","prompt":"Jutro Marek ___ pociągiem do Gdańska.","options":["idzie","jedzie","jadę","jedzą"],"correct":1,"explanation":"With a vehicle (pociągiem) and to another town use jechać; Marek takes the \"he\" form jedzie.","optionNotes":["Idzie is iść: on foot, not by train.",null,"Jadę is the ja form (I am going).","Jedzą is \"they eat\" (jeść)."],"category":"verbs"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-18","topic":"a1-verbs-past-tense-basics","type":"multiple-choice","kind":"form","prompt":"— Gdzie byłaś wczoraj, Ola? — ___ w pracy.","options":["Byłem","Był","Jestem","Byłam"],"correct":3,"explanation":"Ola is a woman talking about herself in the past: byłam.","optionNotes":["Byłem is what a man says.","Był is the \"he\" form.","Jestem is the present; wczoraj needs the past.",null],"category":"verbs"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-19","topic":"a1-verbs-past-tense-basics","type":"find-error","tokens":["Wczoraj","Anna","czytał","ciekawą","książkę."],"errorRange":[2,2],"fixes":["czytała","przeczytała"],"explanation":"Anna is a woman, so the past form ends in -ła: czytała.","category":"verbs"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-20","topic":"a1-cases-instrumental-identity","type":"transformation","source":"Pan Nowak to dobry kucharz.","keyword":"jest","before":"Pan Nowak","after":".","answers":["jest dobrym kucharzem"],"explanation":"A job after a form of być takes the instrumental: adjective -ym, noun -em: dobrym kucharzem.","category":"cases"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-21","topic":"a1-cases-genitive-basics","type":"multiple-choice","kind":"form","prompt":"W lodówce nie ma ___.","options":["mleko","mlekiem","mleka","mleku"],"correct":2,"explanation":"Nie ma (there isn't) always takes the genitive: mleko → mleka.","optionNotes":["Mleko is the nominative.","Mlekiem is the instrumental: kawa z mlekiem.",null,"Mleku is the locative: w mleku."],"category":"cases"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-22","topic":"a1-cases-genitive-basics","type":"gap-fill","context":"On Friday I'm going to Kraków, and on Saturday to Warsaw.","text":"W piątek jadę do {{1}}, a w sobotę do {{2}}.","gaps":[{"accepted":["Krakowa"],"hint":"(Kraków)"},{"accepted":["Warszawy"],"hint":"(Warszawa)"}],"explanation":"Do takes the genitive: Kraków → Krakowa, Warszawa → Warszawy.","category":"cases"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-23","topic":"a1-cases-locative-places","type":"multiple-choice","kind":"form","prompt":"Mieszkam w ___.","options":["Polsce","Polska","Polskę","Polski"],"correct":0,"explanation":"W (in) + the locative: Polska → w Polsce (-a → -e, and k → c).","optionNotes":[null,"Polska is the nominative.","Polskę is the accusative.","Polski is the genitive: z Polski, do Polski."],"category":"cases"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-24","topic":"a1-functions-personal-details","type":"multiple-choice","kind":"function","prompt":"— Ile masz lat? — ___","options":["Jestem dwadzieścia dwa lata.","Mam dwadzieścia dwa lata.","Mam dwadzieścia dwa lat.","Jestem dwadzieścia dwa."],"correct":1,"explanation":"Age uses mieć, and after a number ending in 2, 3 or 4 (not 12–14) say lata.","optionNotes":["Age uses mieć (have), not być.",null,"After dwadzieścia dwa say lata, not lat.","Age uses mieć … lat, not być."],"category":"functions"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-25","topic":"a1-functions-time-dates","type":"multiple-choice","kind":"form","prompt":"— Która godzina? — Jest ___. (7:00)","options":["siedem","siódmej","siódmy","siódma"],"correct":3,"explanation":"The hour is the feminine \"seventh\": Jest siódma.","optionNotes":["Siedem is the ordinary number; hours use siódma.","Siódmej is the form after o (at): o siódmej.","Siódmy is masculine; godzina is feminine.",null],"category":"functions"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-26","topic":"a1-functions-time-dates","type":"short-answer","prompt":"Lekcja jest o ___. (9:00)","accepted":["dziewiątej"],"explanation":"After o (at) the hour takes -ej: o dziewiątej.","category":"functions"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-27","topic":"a1-functions-asking-to-repeat","type":"multiple-choice","kind":"function","prompt":"The waiter speaks very fast. You say politely:","options":["Proszę mówisz wolniej.","Proszę mówić szybciej.","Proszę mówić wolniej.","Mówię wolniej."],"correct":2,"explanation":"Proszę + infinitive is the polite request: Proszę mówić wolniej.","optionNotes":["After proszę the verb is the infinitive, not the ty form.","Szybciej means \"faster\".",null,"Mówię wolniej means \"I speak more slowly\"."],"category":"functions"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-28","topic":"a1-vocabulary-family-people","type":"multiple-choice","kind":"meaning","prompt":"Siostra mojej mamy to moja ___.","options":["babcia","ciocia","córka","żona"],"correct":1,"explanation":"Your mum's sister is your aunt: ciocia.","optionNotes":["Babcia is a grandmother (your mum's or your dad's mother).",null,"Córka is a daughter.","Żona is a wife."],"category":"vocabulary"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-29","topic":"a1-vocabulary-home-city","type":"multiple-choice","kind":"meaning","prompt":"Kupuję chleb i ser w ___.","options":["szpitalu","kinie","hotelu","sklepie"],"correct":3,"explanation":"You buy bread and cheese in a shop: w sklepie.","optionNotes":["Szpital is a hospital.","Kino is a cinema.","Hotel is a hotel.",null],"category":"vocabulary"},{"level":"A1","tags":[],"setId":"final-a1","id":"final-a1-30","topic":"a1-vocabulary-numbers-days-months","type":"short-answer","prompt":"W ___ jedziemy do Gdańska. (sierpień)","accepted":["sierpniu"],"explanation":"In + a month: w sierpniu. The month keeps its small letter.","category":"vocabulary"}]};
